from fractions import Fraction


class CalcError(Exception):
    def __init__(self, message: str, position: int):
        super().__init__(message)
        self.position = position


def evaluate(expr: str) -> Fraction:
    parser = _Parser(expr)
    return parser.parse()


class _Parser:
    def __init__(self, expr: str):
        self.expr = expr
        self.pos = 0

    def _skip_whitespace(self):
        while self.pos < len(self.expr) and self.expr[self.pos] in ' \t':
            self.pos += 1

    def _peek(self):
        self._skip_whitespace()
        if self.pos < len(self.expr):
            return self.expr[self.pos]
        return None

    def _parse(self) -> Fraction:
        # Phase 1: Syntax Check
        self.pos = 0
        try:
            self._check_expression()
        except CalcError:
            raise
        # Phase 2: Evaluation
        self.pos = 0
        result = self._eval_expression()

        self._skip_whitespace()
        if self.pos < len(self.expr):
            # This shouldn't happen if check_expression worked correctly, 
            # but just in case of bugs or edge cases in the check phase
            raise CalcError("Unexpected character", self.pos)

        return result

    # --- Syntax Checking Methods ---

    def _check_expression(self):
        self._check_term()
        while True:
            c = self._peek()
            if c in '+-':
                self.pos += 1
                self._check_term()
            else:
                break

    def _check_term(self):
        self._check_factor()
        while True:
            c = self._peek()
            if c in '*/':
                self.pos += 1
                self._check_factor()
            else:
                break

    def _check_factor(self):
        c = self._peek()
        if c is None:
            raise CalcError("Unexpected end of input", self.pos)

        if c == '-':
            self.pos += 1
            self._check_factor()
        elif c == '(':
            self.pos += 1
            self._check_expression()
            c = self._peek()
            if c != ')':
                if c is None:
                    raise CalcError("Expected ')'", self.pos)
                raise CalcError("Expected ')'", self.pos)
            self.pos += 1
        elif c.isdigit():
            self._check_number()
        else:
            raise CalcError("Unexpected character", self.pos)

    def _check_number(self):
        start = self.pos
        if self.pos >= len(self.expr) or not self.expr[self.pos].isdigit():
            raise CalcError("Expected a number", self.pos)

        while self.pos < len(self.expr) and self.expr[self.pos].isdigit():
            self.pos += 1

        if self.pos < len(self.expr) and self.expr[self.pos] == '.':
            self.pos += 1
            if self.pos >= len(self.expr) or not self.expr[self.pos].isdigit():
                raise CalcError("Expected digits after decimal point", self.pos)
            while self.pos < len(self.expr) and self.expr[self.pos].isdigit():
                self.pos += 1

    # --- Evaluation Methods ---

    def _eval_expression(self) -> Fraction:
        left = self._eval_term()
        while True:
            c = self._peek()
            if c in '+-':
                op = c
                self.pos += 1
                right = self._eval_term()
                if op == '+':
                    left = left + right
                else:
                    left = left - right
            else:
                break
        return left

    def _eval_term(self) -> Fraction:
        left = self._eval_factor()
        while True:
            c = self._peek()
            if c in '*/':
                op = c
                op_pos = self.pos
                self.pos += 1
                right = self._eval_factor()
                if op == '*':
                    left = left * right
                else:
                    if right == 0:
                        raise CalcError("Division by zero", op_pos)
                    left = left / right
            else:
                break
        return left

    def _eval_factor(self) -> Fraction:
        c = self._peek()
        if c is None:
            raise CalcError("Unexpected end of input", self.pos)

        if c == '-':
            self.pos += 1
            return -self._eval_factor()
        elif c == '(':
            self.pos += 1
            val = self._eval_expression()
            c = self._peek()
            if c != ')':
                # Syntax error should have been caught in Phase 1, 
                # but raise just in case
                if c is None:
                    raise CalcError("Expected ')'", self.pos)
                raise CalcError("Expected ')'", self.pos)
            self.pos += 1
            return val
        elif c.isdigit():
            return self._eval_number()
        else:
            raise CalcError("Unexpected character", self.pos)

    def _eval_number(self) -> Fraction:
        start = self.pos
        if self.pos >= len(self.expr) or not self.expr[self.pos].isdigit():
            raise CalcError("Expected a number", self.pos)

        while self.pos < len(self.expr) and self.expr[self.pos].isdigit():
            self.pos += 1

        if self.pos < len(self.expr) and self.expr[self.pos] == '.':
            self.pos += 1
            while self.pos < len(self.expr) and self.expr[self.pos].isdigit():
                self.pos += 1

            num_str = self.expr[start:self.pos]
            int_part_str, frac_part_str = num_str.split('.')
            int_val = int(int_part_str) if int_part_str else 0
            frac_val = int(frac_part_str)
            denominator = 10 ** len(frac_part_str)
            return Fraction(int_val * denominator + frac_val, denominator)
        else:
            num_str = self.expr[start:self.pos]
            return Fraction(int(num_str), 1)
