        result = self._parse_expression()

        self._skip_whitespace()
        if self.pos < len(self.expr):
            raise CalcError("Unexpected character after expression", self.pos)

        return result

    def _parse_expression(self) -> Fraction:
        left = self._parse_term()
        while True:
            c = self._peek()
            if c in '+-':
                op = c
                self.pos += 1
                right = self._parse_term()
                if op == '+':
                    left = left + right
                else:
                    left = left - right
            else:
                break
        return left

    def _parse_term(self) -> Fraction:
        left = self._parse_factor()
        while True:
            c = self._peek()
            if c in '*/':
                op = c
                op_pos = self.pos
                self.pos += 1
                right = self._parse_factor()
                if op == '*':
                    left = left * right
                else:
                    if right == 0:
                        raise CalcError("Division by zero", op_pos)
                    left = left / right
            else:
                break
        return left

    def _parse_factor(self) -> Fraction:
        c = self._peek()
        if c is None:
            raise CalcError("Unexpected end of input", self.pos)

        if c == '-':
            self.pos += 1
            val = self._parse_factor()
            return -val
        elif c == '(':
            self.pos += 1
            val = self._parse_expression()
            c = self._peek()
            if c != ')':
                if c is None:
                    raise CalcError("Expected ')'", self.pos)
                raise CalcError("Expected ')'", self.pos)
            self.pos += 1
            return val
        elif c.isdigit():
            return self._parse_number()
        else:
            raise CalcError("Unexpected character", self.pos)

    def _parse_number(self) -> Fraction:
        start = self.pos
        if self.pos >= len(self.expr) or not self.expr[self.pos].isdigit():
            raise CalcError("Expected a number", self.pos)

        while self.pos < len(self.expr) and self.expr[self.pos].isdigit():
            self.pos += 1

        if self.pos < len(self.expr) and self.expr[self.pos] == '.':
            # Only consume the dot if followed by at least one digit
            if self.pos + 1 < len(self.expr) and self.expr[self.pos + 1].isdigit():
                self.pos += 1 # consume '.'
                while self.pos < len(self.expr) and self.expr[self.pos].isdigit():
                    self.pos += 1

                num_str = self.expr[start:self.pos]
                int_part_str, frac_part_str = num_str.split('.')
                int_val = int(int_part_str)
                frac_val = int(frac_part_str)
                denominator = 10 ** len(frac_part_str)
                return Fraction(int_val * denominator + frac_val, denominator)
            else:
                # '.' is present but not part of a valid decimal number.
                # Do not consume it. Let the caller handle it as an unexpected character/token.
                # The integer part has already been parsed.
                num_str = self.expr[start:self.pos]
                return Fraction(int(num_str), 1)
        else:
            num_str = self.expr[start:self.pos]
            return Fraction(int(num_str), 1)
