"""Tokenization for the tmpl template language."""

from __future__ import annotations

import typing


class TemplateError(Exception):
    """Base class for all tmpl errors."""

    def __init__(self, message: str, lineno: int) -> None:
        super().__init__(message, lineno)
        self.message = message
        self.lineno = lineno

    def __str__(self) -> str:
        return f"line {self.lineno}: {self.message}"


class TemplateSyntaxError(TemplateError):
    """Raised for template syntax problems."""


class TemplateRenderError(TemplateError):
    """Raised for problems that surface while rendering."""


class Token(typing.NamedTuple):
    kind: str
    value: str
    lineno: int


def tokenize(source: str) -> list[Token]:
    """Split *source* into text, variable and block tokens.

    Comments are dropped.  A tag's value is the text between the opening
    and closing delimiters with surrounding whitespace stripped.  The
    ``lineno`` of every token is the line on which the token (or, for tags,
    the opening delimiter) starts.
    """
    tokens: list[Token] = []
    i = 0
    n = len(source)
    text_start = 0

    while i < n:
        if source.startswith("{{", i):
            _flush_text(tokens, source, text_start, i)
            end = source.find("}}", i + 2)
            if end == -1:
                raise TemplateSyntaxError(
                    "unclosed variable tag", _line_of(source, i)
                )
            value = source[i + 2 : end].strip()
            tokens.append(Token("var", value, _line_of(source, i)))
            i = end + 2
            text_start = i
        elif source.startswith("{%", i):
            _flush_text(tokens, source, text_start, i)
            end = source.find("%}", i + 2)
            if end == -1:
                raise TemplateSyntaxError(
                    "unclosed block tag", _line_of(source, i)
                )
            value = source[i + 2 : end].strip()
            tokens.append(Token("block", value, _line_of(source, i)))
            i = end + 2
            text_start = i
        elif source.startswith("{#", i):
            _flush_text(tokens, source, text_start, i)
            end = source.find("#}", i + 2)
            if end == -1:
                raise TemplateSyntaxError(
                    "unclosed comment tag", _line_of(source, i)
                )
            # Comment: do not emit a token, but keep text_start at the
            # *start* of the comment so that text on either side of the
            # comment stays separate.
            i = end + 2
            text_start = i
        else:
            i += 1

    _flush_text(tokens, source, text_start, n)
    return tokens


def _flush_text(
    tokens: list[Token], source: str, start: int, end: int
) -> None:
    if end <= start:
        return
    tokens.append(Token("text", source[start:end], _line_of(source, start)))


def _line_of(source: str, index: int) -> int:
    return source.count("\n", 0, index) + 1
