"""Parse template tokens into a tree of nodes."""

from __future__ import annotations

import re
import typing

from .lexer import (
    TemplateSyntaxError,
    Token,
    tokenize,
)

# ---------------------------------------------------------------------------
# Node types
# ---------------------------------------------------------------------------

Node = typing.Union["Text", "Var", "For", "If"]


class Text:
    __slots__ = ("value",)

    def __init__(self, value: str) -> None:
        self.value = value


class Var:
    __slots__ = ("expr", "lineno")

    def __init__(self, expr: "ValueExpr", lineno: int) -> None:
        self.expr = expr
        self.lineno = lineno


class For:
    __slots__ = ("var", "iter_expr", "body", "else_body", "lineno")

    def __init__(
        self,
        var: str,
        iter_expr: "ValueExpr",
        body: list[Node],
        else_body: list[Node],
        lineno: int,
    ) -> None:
        self.var = var
        self.iter_expr = iter_expr
        self.body = body
        self.else_body = else_body
        self.lineno = lineno


class If:
    __slots__ = ("branches", "else_body", "lineno")

    def __init__(
        self,
        branches: list[typing.Tuple["Condition", list[Node]]],
        else_body: list[Node],
        lineno: int,
    ) -> None:
        self.branches = branches
        self.else_body = else_body
        self.lineno = lineno


# ---------------------------------------------------------------------------
# Expression AST
# ---------------------------------------------------------------------------


class ValueExpr:
    pass


class AtomExpr(ValueExpr):
    __slots__ = ("kind", "value", "path")

    def __init__(
        self,
        kind: str,
        value: typing.Any,
        path: list[str | int] | None = None,
    ) -> None:
        # kind is "string", "int", or "var"
        self.kind = kind
        self.value = value
        self.path = path


class Filter(ValueExpr):
    __slots__ = ("name", "arg", "arg_kind", "sub")

    def __init__(
        self,
        name: str,
        arg: typing.Any,
        arg_kind: str | None,
        sub: ValueExpr,
    ) -> None:
        self.name = name
        self.arg = arg
        self.arg_kind = arg_kind  # "str", "int" or None
        self.sub = sub


class Condition:
    pass


class BareValue(Condition):
    __slots__ = ("expr",)

    def __init__(self, expr: ValueExpr) -> None:
        self.expr = expr


class Comparison(Condition):
    __slots__ = ("left", "op", "right")

    def __init__(
        self, left: ValueExpr, op: str, right: ValueExpr
    ) -> None:
        self.left = left
        self.op = op
        self.right = right


class Not(Condition):
    __slots__ = ("sub",)

    def __init__(self, sub: Condition) -> None:
        self.sub = sub


class And(Condition):
    __slots__ = ("left", "right")

    def __init__(self, left: Condition, right: Condition) -> None:
        self.left = left
        self.right = right


class Or(Condition):
    __slots__ = ("left", "right")

    def __init__(self, left: Condition, right: Condition) -> None:
        self.left = left
        self.right = right


# ---------------------------------------------------------------------------
# Expression parsing
# ---------------------------------------------------------------------------

_NAME_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")
_RESERVED = {"and", "or", "not", "in"}


def _tokenize_expr(text: str, lineno: int) -> list[tuple[str, str]]:
    """Return a list of (kind, value) pairs for a value expression.

    Kinds: "string", "int", "name", "dot", "pipe", "colons".
    Whitespace is skipped.
    """
    tokens: list[tuple[str, str]] = []
    i = 0
    n = len(text)
    while i < n:
        ch = text[i]
        if ch.isspace():
            i += 1
        elif ch in "\"'":
            quote = ch
            i += 1
            j = i
            while j < n and text[j] != quote:
                j += 1
            if j >= n:
                raise TemplateSyntaxError(
                    "unterminated string literal", lineno
                )
            tokens.append(("string", text[i:j]))
            i = j + 1
        elif ch == "-":
            # Could be a negative integer
            j = i + 1
            if j < n and text[j].isdigit():
                while j < n and text[j].isdigit():
                    j += 1
                # Make sure next char is not a name-start (so "-3x" fails)
                if j >= n or not (text[j].isalnum() or text[j] == "_"):
                    tokens.append(("int", text[i:j]))
                    i = j
                    continue
            raise TemplateSyntaxError(
                f"unexpected character {ch!r}", lineno
            )
        elif ch.isdigit():
            j = i
            while j < n and text[j].isdigit():
                j += 1
            tokens.append(("int", text[i:j]))
            i = j
        elif _NAME_RE.match(text[i:]):
            m = _NAME_RE.match(text[i:])
            assert m is not None
            name = m.group(0)
            if name in _RESERVED:
                # Reserved words are not valid names in value expressions
                raise TemplateSyntaxError(
                    f"reserved word {name!r} used as name", lineno
                )
            tokens.append(("name", name))
            i += len(name)
        elif ch == ".":
            tokens.append(("dot", "."))
            i += 1
        elif ch == "|":
            tokens.append(("pipe", "|"))
            i += 1
        elif ch == ":":
            tokens.append(("colon", ":"))
            i += 1
        else:
            raise TemplateSyntaxError(
                f"unexpected character {ch!r}", lineno
            )
    return tokens


class _ExprParser:
    def __init__(self, tokens: list[tuple[str, str]], lineno: int) -> None:
        self.tokens = tokens
        self.pos = 0
        self.lineno = lineno

    def peek(self) -> tuple[str, str] | None:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def next(self) -> tuple[str, str]:
        tok = self.peek()
        if tok is None:
            raise TemplateSyntaxError("unexpected end of expression", self.lineno)
        self.pos += 1
        return tok

    def parse_value(self) -> ValueExpr:
        expr = self._parse_atom()
        while self.peek() is not None and self.peek()[0] == "pipe":
            self.next()  # consume '|'
            name_tok = self.next()
            if name_tok[0] != "name":
                raise TemplateSyntaxError(
                    "expected filter name", self.lineno
                )
            name = name_tok[1]
            arg = None
            arg_kind = None
            if self.peek() is not None and self.peek()[0] == "colon":
                self.next()  # consume ':'
                arg_tok = self.next()
                if arg_tok[0] == "string":
                    arg = arg_tok[1]
                    arg_kind = "str"
                elif arg_tok[0] == "int":
                    arg = int(arg_tok[1])
                    arg_kind = "int"
                else:
                    raise TemplateSyntaxError(
                        "filter argument must be a string or integer literal",
                        self.lineno,
                    )
            expr = Filter(name, arg, arg_kind, expr)
        return expr

    def _parse_atom(self) -> ValueExpr:
        tok = self.peek()
        if tok is None:
            raise TemplateSyntaxError("empty expression", self.lineno)
        if tok[0] == "string":
            self.next()
            return AtomExpr("string", tok[1])
        if tok[0] == "int":
            self.next()
            return AtomExpr("int", int(tok[1]))
        if tok[0] == "name":
            self.next()
            path: list[str | int] = [tok[1]]
            while self.peek() is not None and self.peek()[0] == "dot":
                self.next()  # consume '.'
                seg = self.next()
                if seg[0] == "name":
                    if seg[1] in _RESERVED:
                        raise TemplateSyntaxError(
                            f"reserved word {seg[1]!r} used as segment",
                            self.lineno,
                        )
                    path.append(seg[1])
                elif seg[0] == "int":
                    path.append(int(seg[1]))
                else:
                    raise TemplateSyntaxError(
                        "segment must be a name or integer", self.lineno
                    )
            return AtomExpr("var", None, path)
        raise TemplateSyntaxError(
            f"expected string, integer or variable, got {tok[1]!r}",
            self.lineno,
        )


def parse_value_expr(text: str, lineno: int) -> ValueExpr:
    tokens = _tokenize_expr(text, lineno)
    if not tokens:
        raise TemplateSyntaxError("empty expression", lineno)
    parser = _ExprParser(tokens, lineno)
    expr = parser.parse_value()
    if parser.pos != len(parser.tokens):
        raise TemplateSyntaxError(
            f"unexpected token {parser.tokens[parser.pos][1]!r}",
            lineno,
        )
    return expr


# ---------------------------------------------------------------------------
# Condition parsing
# ---------------------------------------------------------------------------

_COMP_OPS = {"==", "!=", "<=", ">=", "<", ">"}


def _tokenize_cond(text: str, lineno: int) -> list[tuple[str, str]]:
    """Tokenize a condition expression.

    Returns tokens of kinds: "string", "int", "name", "op", "dot", "pipe",
    "colon", "and", "or", "not".
    """
    tokens: list[tuple[str, str]] = []
    i = 0
    n = len(text)
    while i < n:
        ch = text[i]
        if ch.isspace():
            i += 1
        elif ch in "\"'":
            quote = ch
            i += 1
            j = i
            while j < n and text[j] != quote:
                j += 1
            if j >= n:
                raise TemplateSyntaxError(
                    "unterminated string literal", lineno
                )
            tokens.append(("string", text[i:j]))
            i = j + 1
        elif ch == "-" and i + 1 < n and text[i + 1].isdigit():
            j = i + 1
            while j < n and text[j].isdigit():
                j += 1
            if j >= n or not (text[j].isalnum() or text[j] == "_"):
                tokens.append(("int", text[i:j]))
                i = j
            else:
                raise TemplateSyntaxError(
                    f"unexpected character {ch!r}", lineno
                )
        elif ch.isdigit():
            j = i
            while j < n and text[j].isdigit():
                j += 1
            tokens.append(("int", text[i:j]))
            i = j
        elif ch == "=" and i + 1 < n and text[i + 1] == "=":
            tokens.append(("op", "=="))
            i += 2
        elif ch == "!" and i + 1 < n and text[i + 1] == "=":
            tokens.append(("op", "!="))
            i += 2
        elif ch == "<":
            if i + 1 < n and text[i + 1] == "=":
                tokens.append(("op", "<="))
                i += 2
            else:
                tokens.append(("op", "<"))
                i += 1
        elif ch == ">":
            if i + 1 < n and text[i + 1] == "=":
                tokens.append(("op", ">="))
                i += 2
            else:
                tokens.append(("op", ">"))
                i += 1
        elif _NAME_RE.match(text[i:]):
            m = _NAME_RE.match(text[i:])
            assert m is not None
            name = m.group(0)
            if name == "and":
                tokens.append(("and", name))
            elif name == "or":
                tokens.append(("or", name))
            elif name == "not":
                tokens.append(("not", name))
            elif name in _RESERVED:
                raise TemplateSyntaxError(
                    f"reserved word {name!r} used as name", lineno
                )
            else:
                tokens.append(("name", name))
            i += len(name)
        elif ch == ".":
            tokens.append(("dot", "."))
            i += 1
        elif ch == "|":
            tokens.append(("pipe", "|"))
            i += 1
        elif ch == ":":
            tokens.append(("colon", ":"))
            i += 1
        else:
            raise TemplateSyntaxError(
                f"unexpected character {ch!r}", lineno
            )
    return tokens


class _CondParser:
    def __init__(self, tokens: list[tuple[str, str]], lineno: int) -> None:
        self.tokens = tokens
        self.pos = 0
        self.lineno = lineno

    def peek(self) -> tuple[str, str] | None:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def next(self) -> tuple[str, str]:
        tok = self.peek()
        if tok is None:
            raise TemplateSyntaxError("unexpected end of condition", self.lineno)
        self.pos += 1
        return tok

    def parse(self) -> Condition:
        cond = self._parse_or()
        if self.pos != len(self.tokens):
            raise TemplateSyntaxError(
                f"unexpected token {self.tokens[self.pos][1]!r}",
                self.lineno,
            )
        return cond

    def _parse_or(self) -> Condition:
        left = self._parse_and()
        while self.peek() is not None and self.peek()[0] == "or":
            self.next()
            right = self._parse_and()
            left = Or(left, right)
        return left

    def _parse_and(self) -> Condition:
        left = self._parse_not()
        while self.peek() is not None and self.peek()[0] == "and":
            self.next()
            right = self._parse_not()
            left = And(left, right)
        return left

    def _parse_not(self) -> Condition:
        if self.peek() is not None and self.peek()[0] == "not":
            self.next()
            sub = self._parse_not()
            return Not(sub)
        return self._parse_comparison()

    def _parse_comparison(self) -> Condition:
        left = self._parse_value()
        tok = self.peek()
        if tok is not None and tok[0] == "op":
            op = tok[1]
            self.next()
            right = self._parse_value()
            # Check that we don't have another comparison operator
            # (chained comparisons like a < b < c are not allowed)
            nxt = self.peek()
            if nxt is not None and nxt[0] == "op":
                raise TemplateSyntaxError(
                    "chained comparisons are not allowed", self.lineno
                )
            return Comparison(left, op, right)
        return BareValue(left)

    def _parse_value(self) -> ValueExpr:
        # Reuse the value expression parser logic
        # We need to parse a value expression from the current position
        expr_tokens: list[tuple[str, str]] = []
        while self.pos < len(self.tokens):
            tok = self.tokens[self.pos]
            if tok[0] in ("and", "or", "not"):
                break
            if tok[0] == "op":
                # If we're in _parse_comparison, the op is handled there
                # But if we encounter an op here unexpectedly, stop
                break
            expr_tokens.append(tok)
            self.pos += 1
        if not expr_tokens:
            raise TemplateSyntaxError("empty expression in condition", self.lineno)
        parser = _ExprParser(expr_tokens, self.lineno)
        expr = parser.parse_value()
        if parser.pos != len(parser.tokens):
            raise TemplateSyntaxError(
                f"unexpected token in expression", self.lineno
            )
        return expr


def parse_condition(text: str, lineno: int) -> Condition:
    tokens = _tokenize_cond(text, lineno)
    if not tokens:
        raise TemplateSyntaxError("empty condition", lineno)
    parser = _CondParser(tokens, lineno)
    return parser.parse()


