        if fname not in FILTERS: raise TSyn(f"unknown filter {fname!r}",line)
        arg=None; argk=None
        if peek() and peek()[0]=="colon":
            nxt()
            a=nxt()
            if a[0]=="str": arg=a[1]; argk="str"
            elif a[0]=="int": arg=a[1]; argk="int"
            else: raise TSyn("bad filter arg",line)
        if fname in FILTERS_NO_ARG and argk is not None:
            raise TSyn(f"filter {fname} takes no argument",line)
        if fname in FILTERS_STR_ARG and argk!="str":
            raise TSyn(f"filter {fname} needs a string argument",line)
        if fname in FILTERS_INT_ARG:
            if argk!="int" or arg<0:
                raise TSyn(f"filter {fname} needs a non-negative integer argument",line)
        node=("filter",fname,arg,argk,node)
    if pos!=len(toks): raise TSyn("trailing tokens",line)
    return node

# condition tokens
def cond_tokens(text,line):
    out=[]; i=0; n=len(text)
    while i<n:
        c=text[i]
        if c.isspace(): i+=1
        elif c in "\"'":
            q=c; i+=1; j=i
            while j<n and text[j]!=q: j+=1
            if j>=n: raise TSyn("unterminated string literal",line)
            out.append(("str",text[i:j])); i=j+1
        elif c.isdigit():
            j=i
            while j<n and text[j].isdigit(): j+=1
            out.append(("int",int(text[i:j]))); i=j
        elif c=="-" and i+1<n and text[i+1].isdigit():
            j=i+1
            while j<n and text[j].isdigit(): j+=1
            if j>=n or not (text[j].isalnum() or text[j]=="_"):
                out.append(("int",int(text[i:j]))); i=j
            else: raise TSyn("bad number",line)
        elif c.isalpha() or c=="_":
            j=i
            while j<n and (text[j].isalnum() or text[j]=="_"): j+=1
            w=text[i:j]
            if w=="and": out.append(("and","and"))
            elif w=="or": out.append(("or","or"))
            elif w=="not": out.append(("not","not"))
            elif w=="in": raise TSyn("in is not allowed here",line)
            else: out.append(("name",w))
            i=j
        elif c=="=" and i+1<n and text[i+1]=="=":
            out.append(("op","==")); i+=2
        elif c=="!" and i+1<n and text[i+1]=="=":
            out.append(("op","!=")); i+=2
        elif c=="<" :
            if i+1<n and text[i+1]=="=": out.append(("op","<=")); i+=2
            else: out.append(("op","<")); i+=1
        elif c==">":
            if i+1<n and text[i+1]=="=": out.append(("op",">=")); i+=2
            else: out.append(("op",">")); i+=1
        elif c==".": out.append(("dot",".")); i+=1
        elif c=="|": out.append(("pipe","|")); i+=1
        elif c==":": out.append(("colon",":")); i+=1
        else: raise TSyn(f"unexpected {c!r}",line)
    return out

OPS={"==","!=","<=",">=", "<",">"}
def parse_cond(text,line):
    toks=cond_tokens(text,line)
    if not toks: raise TSyn("empty condition",line)
    pos=0
    def peek(): return toks[pos] if pos<len(toks) else None
    def nxt():
        nonlocal pos
        if pos>=len(toks): raise TSyn("unexpected end of condition",line)
        t=toks[pos]; pos+=1; return t
    def stop(kinds):
        return peek() and peek()[0] in kinds
    def parse_or():
        l=parse_and()
        while peek() and peek()[0]=="or":
            nxt(); r=parse_and(); l=("or",l,r)
        return l
    def parse_and():
        l=parse_not()
        while peek() and peek()[0]=="and":
            nxt(); r=parse_not(); l=("and",l,r)
        return l
    def parse_not():
        if peek() and peek()[0]=="not":
            nxt(); return ("not",parse_not())
        return parse_cmp()
    def parse_cmp():
        l=parse_val()
        if peek() and peek()[0]=="op":
            op=nxt()[1]
            r=parse_val()
            if peek() and peek()[0]=="op":
                raise TSyn("chained comparison not allowed",line)
            return ("cmp",l,op,r)
        return ("bare",l)
    def parse_val():
        # collect value tokens until and/or/not/op
        vtoks=[]
        while pos<len(toks):
            k=toks[pos][0]
            if k in ("and","or","not","op"): break
            vtoks.append(toks[pos]); pos+=1
        if not vtoks: raise TSyn("empty value expression",line)
        # parse these as value
        vpos=0
        def vp(): return vtoks[vpos] if vpos<len(vtoks) else None
        def vn():
            nonlocal vpos
            if vpos>=len(vtoks): raise TSyn("unexpected end of value",line)
            t=vtoks[vpos]; vpos+=1; return t
        t=vn()
        if t[0]=="str": atom=("str",t[1])
        elif t[0]=="int": atom=("int",t[1])
        elif t[0]=="name":
            path=[t[1]]
            while vp() and vp()[0]=="dot":
                vn(); s=vn()
                if s[0]=="name": path.append(s[1])
                elif s[0]=="int": path.append(s[1])
                else: raise TSyn("bad segment",line)
            atom=("var",path)
        else: raise TSyn("bad atom",line)
        node=atom
        while vp() and vp()[0]=="pipe":
            vn(); nm=vn()
            if nm[0]!="name": raise TSyn("expected filter name",line)
            fname=nm[1]
            if fname not in FILTERS: raise TSyn(f"unknown filter {fname!r}",line)
            arg=None; argk=None
            if vp() and vp()[0]=="colon":
                vn(); a=vn()
                if a[0]=="str": arg=a[1]; argk="str"
                elif a[0]=="int": arg=a[1]; argk="int"
                else: raise TSyn("bad filter arg",line)
            if fname in FILTERS_NO_ARG and argk is not None:
                raise TSyn(f"filter {fname} takes no argument",line)
            if fname in FILTERS_STR_ARG and argk!="str":
                raise TSyn(f"filter {fname} needs a string argument",line)
            if fname in FILTERS_INT_ARG:
                if argk!="int" or arg<0: raise TSyn(f"filter {fname} needs non-negative int arg",line)
            node=("filter",fname,arg,argk,node)
        if vpos!=len(vtoks): raise TSyn("trailing tokens in value",line)
        return node
    c=parse_or()
    if pos!=len(toks): raise TSyn("trailing tokens",line)
    return c

# parse nodes
def parse(source):
    toks=tokenize(source)
    nodes, i = parse_nodes(toks, 0)
    return nodes

def parse_nodes(toks, i):
    nodes=[]
    n=len(toks)
    while i<n:
        t=toks[i]
        if t.kind=="text":
            if t.value: nodes.append(("text",t.value))
            i+=1
        elif t.kind=="var":
            nodes.append(("var",parse_value(t.value,t.lineno),t.lineno))
            i+=1
        elif t.kind=="block":
            v=t.value
            if v.startswith("for "):
                res=i
                nodes, i, res = parse_for(toks,i)
                nodes.append(nodes[-1]); i=res
            elif v.startswith("if ") or v=="if":
                nodes, i, res = parse_if(toks,i)
                nodes.append(nodes[-1]); i=res
            else:
                raise TSyn(f"unknown statement {v!r}",t.lineno)
    return nodes,i

def parse_for(toks,i):
    t=toks[i]; v=t.value
    # v = "for NAME in EXPR"
    import re
    m=re.match(r'^for\s+([A-Za-z_][A-Za-z0-9_]*)\s+in\s+(.+)$',v)
    if not m: raise TSyn(f"malformed for {v!r}",t.lineno)
    name=m.group(1)
    if name in RESERVED: raise TSyn(f"reserved word {name!r}",t.lineno)
    expr=parse_value(m.group(2).strip(),t.lineno)
    body=[]; else_body=[]; in_else=False; i+=1
    n=len(toks)
    while i<n:
        tk=toks[i]
        if tk.kind=="block":
            bv=tk.value
            if bv=="endfor":
                i+=1; break
            if bv=="else":
                if in_else: raise TSyn("second else",tk.lineno)
                in_else=True; i+=1; continue
            if in_else:
                # nested in else
                if bv.startswith("for "):
                    _,_,ni=parse_for(toks,i); else_body.append(_); i=ni
                elif bv.startswith("if ") or bv=="if":
                    _,_,ni=parse_if(toks,i); else_body.append(_); i=ni
                else:
                    raise TSyn(f"unexpected {bv!r}",tk.lineno)
                continue
            if bv.startswith("for "):
                _,_,ni=parse_for(toks,i); body.append(_); i=ni
            elif bv.startswith("if ") or bv=="if":
                _,_,ni=parse_if(toks,i); body.append(_); i=ni
            else:
                raise TSyn(f"unexpected {bv!r}",tk.lineno)
            continue
        # text/var
        if tk.kind=="text":
            if tk.value:
                (else_body if in_else else body).append(("text",tk.value))
        elif tk.kind=="var":
            (else_body if in_else else body).append(("var",parse_value(tk.value,tk.lineno),tk.lineno))
        i+=1
    else:
        raise TSyn("unterminated for",t.lineno)
    return ("for",name,expr,body,else_body,t.lineno), i, i

def parse_if(toks,i):
    t=toks[i]; v=t.value
    ct=v[2:].strip() if v.startswith("if ") else v[2:].strip()
    if not ct: raise TSyn("missing condition in if",t.lineno)
    cond=parse_cond(ct,t.lineno)
    branches=[(cond,[])]
    else_body=[]; has_else=False; i+=1
    n=len(toks)
    while i<n:
        tk=toks[i]
        if tk.kind=="block":
            bv=tk.value
            if bv.startswith("elif "):
                if has_else: raise TSyn("elif after else",tk.lineno)
                ect=bv[5:].strip()
                if not ect: raise TSyn("missing condition in elif",tk.lineno)
                branches.append((parse_cond(ect,tk.lineno),[]))
                i+=1; continue
            if bv=="else":
                if has_else: raise TSyn("second else",tk.lineno)
                has_else=True; i+=1; continue
            if bv=="endif":
                i+=1; break
            # nested
            target=else_body if has_else else branches[-1][1]
            if bv.startswith("for "):
                _,_,ni=parse_for(toks,i); target.append(_); i=ni
            elif bv.startswith("if ") or bv=="if":
                _,_,ni=parse_if(toks,i); target.append(_); i=ni
            else:
                raise TSyn(f"unexpected {bv!r}",tk.lineno)
            continue
        target=else_body if has_else else branches[-1][1]
        if tk.kind=="text" and tk.value:
            target.append(("text",tk.value))
        elif tk.kind=="var":
            target.append(("var",parse_value(tk.value,tk.lineno),tk.lineno))
        i+=1
    else:
        raise TSyn("unterminated if",t.lineno)
    return ("if",branches,else_body,t.lineno), i, i

# render
def resolve(node, ctx, line):
    if node[0]=="str": return node[1]
    if node[0]=="int": return node[1]
    if node[0]=="var":
        v=ctx.get(node[1][0])
        for seg in node[1][1:]:
            v=seg_get(v,seg)
        return v
    if node[0]=="filter":
        _,fname,arg,argk,sub=node
        return apply_filter(fname,arg,argk,resolve(sub,ctx,line),line)
    raise TRend("bad node",line)

def seg_get(v,seg):
    if v is None: return None
    if isinstance(v,Mapping):
        key=str(seg) if not isinstance(seg,int) else str(seg)
        return v.get(key)
    if isinstance(v,(list,tuple)):
        if isinstance(seg,int) and 0<=seg<len(v): return v[seg]
        return None
    if isinstance(seg,str) and not seg.startswith("_"):
        return getattr(v,seg,None)
    return None

def out_text(v):
    return "" if v is None else str(v)

def apply_filter(fname,arg,argk,v,line):
    if fname=="upper": return out_text(v).upper()
    if fname=="lower": return out_text(v).lower()
    if fname=="trim": return out_text(v).strip()
    if fname=="length":
        if v is None: return 0
        try: return len(v)
        except TypeError: raise TRend("cannot take length of value",line)
    if fname=="first":
        if v is None: return None
        try:
            it=list(v)
        except TypeError:
            raise TRend("value not iterable",line)
        return it[0] if it else None
    if fname=="last":
        if v is None: return None
        try: it=list(v)
        except TypeError: raise TRend("value not iterable",line)
        return it[-1] if it else None
    if fname=="reverse":
        if v is None: return None
        if isinstance(v,str): return v[::-1]
        if isinstance(v,(list,tuple)):
            try: return list(v)[::-1]
            except TypeError: pass
        raise TRend("reverse only on string or list/tuple",line)
    if fname=="join":
        if v is None: return ""
        try:
            return arg.join(out_text(x) for x in v)
        except TypeError:
            raise TRend("join needs iterable",line)
    if fname=="default":
        if v is None or v=="": return arg
        return v
    if fname=="truncate":
        s=out_text(v)
        if len(s)>arg: return s[:arg]+"..."
        return s
    if fname=="items":
        if v is None: return []
        if isinstance(v,Mapping): return list(v.items())
        raise TRend("items only on mapping",line)
    raise TSyn(f"unknown filter {fname!r}",line)

def cmp_vals(lv,op,rv,line):
    if op=="==": return lv==rv
    if op=="!=": return lv!=rv
    try:
        if op=="<": return lv<rv
        if op=="<=": return lv<=rv
        if op==">": return lv>rv
        if op==">=": return lv>=rv
    except TypeError:
        raise TRend(f"cannot compare with {op}",line)
    raise TRend(f"bad op {op}",line)

def eval_cond(node,ctx,line):
    k=node[0]
    if k=="bare": return bool(resolve(node[1],ctx,line))
    if k=="cmp":
        lv=resolve(node[1],ctx,line); rv=resolve(node[3],ctx,line)
        return cmp_vals(lv,node[2],rv,line)
    if k=="not": return not eval_cond(node[1],ctx,line)
    if k=="and":
        if not eval_cond(node[1],ctx,line): return False
        return eval_cond(node[2],ctx,line)
    if k=="or":
        if eval_cond(node[1],ctx,line): return True
        return eval_cond(node[2],ctx,line)
    raise TRend("bad cond",line)

def render_nodes(nodes,ctx,out,line):
    for nd in nodes:
        if nd[0]=="text": out.append(nd[1])
        elif nd[0]=="var":
            v=resolve(nd[1],ctx,nd[2])
            out.append(out_text(v))
        elif nd[0]=="for":
            render_for(nd,ctx,out)
        elif nd[0]=="if":
            render_if(nd,ctx,out)

def render_for(nd,ctx,out):
    _,name,expr,body,else_body,line=nd
    v=resolve(expr,ctx,line)
    if v is None: items=[]
    elif isinstance(v,Mapping): items=list(v.keys())
    elif isinstance(v,str): items=list(v)
    else:
        try: items=list(v)
        except TypeError: raise TRend("value not iterable",line)
    if items:
        L=len(items)
        saved=ctx.get(name)
        has_name=name in ctx
        for idx,it in enumerate(items):
            ctx[name]=it
            ctx["loop"]={"index":idx+1,"index0":idx,"first":idx==0,"last":idx==L-1,"length":L}
            render_nodes(body,ctx,out,line)
        if has_name: ctx[name]=saved
        else: ctx.pop(name,None)
        ctx.pop("loop",None)
    else:
        render_nodes(else_body,ctx,out,line)

def render_if(nd,ctx,out):
    _,branches,else_body,line=nd
    for cond,body in branches:
        if eval_cond(cond,ctx,cond_line(cond,line)):
            render_nodes(body,ctx,out,line); return
    render_nodes(else_body,ctx,out,line)

def cond_line(cond,fallback):
    return fallback

# store line in cond? for now fallback
def make_ctx(d,kwargs):
    ctx=dict(d) if d else {}
    ctx.update(kwargs)
    return ctx

def render(source,context=None,**kwargs):
    nodes=parse(source)
    ctx=make_ctx(context,kwargs)
    out=[]
    render_nodes(nodes,ctx,out,1)
    return "".join(out)

