"""Parse template tokens into a tree of nodes."""

from __future__ import annotations

import re
import typing

from .lexer import Token, TemplateSyntaxError, tokenize

# ---------------------------------------------------------------------------
# Node classes
# ---------------------------------------------------------------------------

Node = typing.Union["Text", "Var", "For", "If"]


class Text:
    __slots__ = ("value",)

    def __init__(self, value: str) -> None:
        self.value = value


class Var:
    __slots__ = ("expr", "lineno")

    def __init__(self, expr: "ValueExpr", lineno: int) -> None:
        self.expr = expr
        self.lineno = lineno


class For:
    __slots__ = ("var", "iter_expr", "body", "else_body", "lineno")

    def __init__(
        self,
        var: str,
        iter_expr: "ValueExpr",
        body: list[Node],
        else_body: list[Node],
        lineno: int,
    ) -> None:
        self.var = var
        self.iter_expr = iter_expr
        self.body = body
        self.else_body = else_body
        self.lineno = lineno


class If:
    __slots__ = ("branches", "else_body", "lineno")

    def __init__(
        self,
        branches: list[typing.Tuple["Condition", list[Node]]],
        else_body: list[Node],
        lineno: int,
    ) -> None:
        self.branches = branches
        self.else_body = else_body
        self.lineno = lineno


# ---------------------------------------------------------------------------
# Expression AST
# ---------------------------------------------------------------------------


class ValueExpr:
    """Base class for value expressions."""


class AtomExpr(ValueExpr):
    __slots__ = ("kind", "value", "path")

    def __init__(self, kind: str, value: typing.Any, path: list[str | int] | None = None) -> None:
        self.kind = kind  # "string", "int", or "var"
        self.value = value
        self.path = path


class Filter(ValueExpr):
    __slots__ = ("name", "arg", "arg_kind", "sub")

    def __init__(self, name: str, arg: typing.Any, arg_kind: str | None, sub: ValueExpr) -> None:
        self.name = name
        self.arg = arg
        self.arg_kind = arg_kind  # "str", "int" or None
        self.sub = sub


class Condition:
    """Base class for condition nodes."""


class BareValue(Condition):
    __slots__ = ("expr",)

    def __init__(self, expr: ValueExpr) -> None:
        self.expr = expr


class Comparison(Condition):
    __slots__ = ("left", "op", "right")

    def __init__(self, left: ValueExpr, op: str, right: ValueExpr) -> None:
        self.left = left
        self.op = op
        self.right = right


class Not(Condition):
    __slots__ = ("sub",)

    def __init__(self, sub: Condition) -> None:
        self.sub = sub


class And(Condition):
    __slots__ = ("left", "right")

    def __init__(self, left: Condition, right: Condition) -> None:
        self.left = left
        self.right = right


class Or(Condition):
    __slots__ = ("left", "right")

    def __init__(self, left: Condition, right: Condition) -> None:
        self.left = left
        self.right = right


# ---------------------------------------------------------------------------
# Expression tokenization
# ---------------------------------------------------------------------------

_NAME_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")
_RESERVED = {"and", "or", "not", "in"}

FILTER_NAMES = {
    "upper", "lower", "trim", "length", "first", "last",
    "reverse", "join", "default", "truncate", "items",
}
FILTERS_NO_ARG = {"upper", "lower", "trim", "length", "first", "last", "reverse", "items"}
FILTERS_STR_ARG = {"join", "default"}
FILTERS_INT_ARG = {"truncate"}


def _expr_tokens(text: str, lineno: int) -> list[tuple[str, typing.Any]]:
    """Tokenize a value expression into (kind, value) pairs."""
    toks: list[tuple[str, typing.Any]] = []
    i = 0
    n = len(text)
    while i < n:
        c = text[i]
        if c.isspace():
            i += 1
        elif c in "\"'":
            q = c
            i += 1
            j = i
            while j < n and text[j] != q:
                j += 1
            if j >= n:
                raise TemplateSyntaxError("unterminated string literal", lineno)
            toks.append(("str", text[i:j]))
            i = j + 1
        elif c.isdigit():
            j = i
            while j < n and text[j].isdigit():
                j += 1
            toks.append(("int", int(text[i:j])))
            i = j
        elif c == "-" and i + 1 < n and text[i + 1].isdigit():
            j = i + 1
            while j < n and text[j].isdigit():
                j += 1
            if j < n and (text[j].isalnum() or text[j] == "_"):
                raise TemplateSyntaxError("malformed integer literal", lineno)
            toks.append(("int", int(text[i:j])))
            i = j
        elif _NAME_RE.match(text[i:]):
            m = _NAME_RE.match(text[i:])
            assert m is not None
            w = m.group(0)
            if w in _RESERVED:
                raise TemplateSyntaxError(f"reserved word {w!r} used as name", lineno)
            toks.append(("name", w))
            i += len(w)
        elif c == ".":
            toks.append(("dot", "."))
            i += 1
        elif c == "|":
            toks.append(("pipe", "|"))
            i += 1
        elif c == ":":
            toks.append(("colon", ":"))
            i += 1
        else:
            raise TemplateSyntaxError(f"unexpected character {c!r} in expression", lineno)
    return toks


def _cond_tokens(text: str, lineno: int) -> list[tuple[str, typing.Any]]:
    """Tokenize a condition expression into (kind, value) pairs."""
    toks: list[tuple[str, typing.Any]] = []
    i = 0
    n = len(text)
    while i < n:
        c = text[i]
        if c.isspace():
            i += 1
        elif c in "\"'":
            q = c
            i += 1
            j = i
            while j < n and text[j] != q:
                j += 1
            if j >= n:
                raise TemplateSyntaxError("unterminated string literal", lineno)
            toks.append(("str", text[i:j]))
            i = j + 1
        elif c.isdigit():
            j = i
            while j < n and text[j].isdigit():
                j += 1
            toks.append(("int", int(text[i:j])))
            i = j
        elif c == "-" and i + 1 < n and text[i + 1].isdigit():
            j = i + 1
            while j < n and text[j].isdigit():
                j += 1
            if j < n and (text[j].isalnum() or text[j] == "_"):
                raise TemplateSyntaxError("malformed integer literal", lineno)
            toks.append(("int", int(text[i:j])))
            i = j
        elif _NAME_RE.match(text[i:]):
            m = _NAME_RE.match(text[i:])
            assert m is not None
            w = m.group(0)
            if w == "and":
                toks.append(("and", "and"))
            elif w == "or":
                toks.append(("or", "or"))
            elif w == "not":
                toks.append(("not", "not"))
            elif w == "in":
                raise TemplateSyntaxError("'in' is not allowed in conditions", lineno)
            else:
                toks.append(("name", w))
            i += len(w)
        elif c == "=" and i + 1 < n and text[i + 1] == "=":
            toks.append(("op", "=="))
            i += 2
        elif c == "!" and i + 1 < n and text[i + 1] == "=":
            toks.append(("op", "!="))
            i += 2
        elif c == "<":
            if i + 1 < n and text[i + 1] == "=":
                toks.append(("op", "<="))
                i += 2
            else:
                toks.append(("op", "<"))
                i += 1
        elif c == ">":
            if i + 1 < n and text[i + 1] == "=":
                toks.append(("op", ">="))
                i += 2
            else:
                toks.append(("op", ">"))
                i += 1
        elif c == ".":
            toks.append(("dot", "."))
            i += 1
        elif c == "|":
            toks.append(("pipe", "|"))
            i += 1
        elif c == ":":
            toks.append(("colon", ":"))
            i += 1
        else:
            raise TemplateSyntaxError(f"unexpected character {c!r} in condition", lineno)
    return toks


# ---------------------------------------------------------------------------
# Expression parsing
# ---------------------------------------------------------------------------


def _parse_value_expr_from_tokens(
    tokens: list[tuple[str, typing.Any]], lineno: int
) -> ValueExpr:
    """Parse a value expression from already-tokenized (kind, value) pairs."""
    pos = 0
    n = len(tokens)

    def peek() -> tuple[str, typing.Any] | None:
        return tokens[pos] if pos < n else None

    def nxt() -> tuple[str, typing.Any]:
        nonlocal pos
        if pos >= n:
            raise TemplateSyntaxError("unexpected end of expression", lineno)
        t = tokens[pos]
        pos += 1
        return t

    # Parse atom
    t = nxt()
    if t[0] == "str":
        node: ValueExpr = AtomExpr("string", t[1])
    elif t[0] == "int":
        node = AtomExpr("int", t[1])
    elif t[0] == "name":
        path: list[str | int] = [t[1]]
        while peek() is not None and peek()[0] == "dot":
            nxt()  # consume dot
            seg = nxt()
            if seg[0] == "name":
                if seg[1] in _RESERVED:
                    raise TemplateSyntaxError(
                        f"reserved word {seg[1]!r} used as segment", lineno
                    )
                path.append(seg[1])
            elif seg[0] == "int":
                path.append(seg[1])
            else:
                raise TemplateSyntaxError("segment must be a name or integer", lineno)
        node = AtomExpr("var", None, path)
    else:
        raise TemplateSyntaxError(
            f"expected string, integer or variable, got {t[1]!r}", lineno
        )

    # Parse filters
    while peek() is not None and peek()[0] == "pipe":
        nxt()  # consume |
        ft = nxt()
        if ft[0] != "name":
            raise TemplateSyntaxError("expected filter name", lineno)
        fname = ft[1]
        if fname not in FILTER_NAMES:
            raise TemplateSyntaxError(f"unknown filter {fname!r}", lineno)
        arg: typing.Any = None
        arg_kind: str | None = None
        if peek() is not None and peek()[0] == "colon":
            nxt()  # consume :
            at = nxt()
            if at[0] == "str":
                arg = at[1]
                arg_kind = "str"
            elif at[0] == "int":
                arg = at[1]
                arg_kind = "int"
            else:
                raise TemplateSyntaxError(
                    "filter argument must be a string or integer literal", lineno
                )
        # Validate argument
        if fname in FILTERS_NO_ARG and arg_kind is not None:
            raise TemplateSyntaxError(f"filter {fname!r} takes no argument", lineno)
        if fname in FILTERS_STR_ARG and arg_kind != "str":
            raise TemplateSyntaxError(
                f"filter {fname!r} requires a string argument", lineno
            )
        if fname in FILTERS_INT_ARG:
            if arg_kind != "int" or arg < 0:
                raise TemplateSyntaxError(
                    f"filter {fname!r} requires a non-negative integer argument", lineno
                )
        node = Filter(fname, arg, arg_kind, node)

    if pos != n:
        raise TemplateSyntaxError(
            f"unexpected token {tokens[pos][1]!r} in expression", lineno
        )
    return node


def parse_value_expr(text: str, lineno: int) -> ValueExpr:
    """Parse a value expression from raw text."""
    toks = _expr_tokens(text, lineno)
    if not toks:
        raise TemplateSyntaxError("empty expression", lineno)
    return _parse_value_expr_from_tokens(toks, lineno)


# ---------------------------------------------------------------------------
# Condition parsing
# ---------------------------------------------------------------------------

_VALUE_STOP_KINDS = {"and", "or", "not", "op"}


def _parse_condition_from_tokens(
    tokens: list[tuple[str, typing.Any]], lineno: int
) -> Condition:
    """Parse a condition from already-tokenized (kind, value) pairs."""
    pos = 0
    n = len(tokens)

    def peek() -> tuple[str, typing.Any] | None:
        return tokens[pos] if pos < n else None

    def nxt() -> tuple[str, typing.Any]:
        nonlocal pos
        if pos >= n:
            raise TemplateSyntaxError("unexpected end of condition", lineno)
        t = tokens[pos]
        pos += 1
        return t

    def parse_or() -> Condition:
        left = parse_and()
        while peek() is not None and peek()[0] == "or":
            nxt()
            right = parse_and()
            left = Or(left, right)
        return left

    def parse_and() -> Condition:
        left = parse_not()
        while peek() is not None and peek()[0] == "and":
            nxt()
            right = parse_not()
            left = And(left, right)
        return left

    def parse_not() -> Condition:
        if peek() is not None and peek()[0] == "not":
            nxt()
            return Not(parse_not())
        return parse_cmp()

    def parse_cmp() -> Condition:
        left = parse_val()
        if peek() is not None and peek()[0] == "op":
            op = nxt()[1]
            right = parse_val()
            if peek() is not None and peek()[0] == "op":
                raise TemplateSyntaxError("chained comparisons are not allowed", lineno)
            return Comparison(left, op, right)
        return BareValue(left)

    def parse_val() -> ValueExpr:
        # Collect tokens belonging to this value expression
        start = pos
        while pos < n and tokens[pos][0] not in _VALUE_STOP_KINDS:
            pos += 1
        sub_tokens = tokens[start:pos]
        if not sub_tokens:
            raise TemplateSyntaxError("empty value expression", lineno)
        return _parse_value_expr_from_tokens(sub_tokens, lineno)

    result = parse_or()
    if pos != n:
        raise TemplateSyntaxError(
            f"unexpected token {tokens[pos][1]!r} in condition", lineno
        )
    return result


def parse_condition(text: str, lineno: int) -> Condition:
    """Parse a condition from raw text."""
    toks = _cond_tokens(text, lineno)
    if not toks:
        raise TemplateSyntaxError("empty condition", lineno)
    return _parse_condition_from_tokens(toks, lineno)


# ---------------------------------------------------------------------------
# Statement / body parsing
# ---------------------------------------------------------------------------

_FOR_RE = re.compile(r"^for\s+([A-Za-z_][A-Za-z0-9_]*)\s+in\s+(.+)$")
_IF_RE = re.compile(r"^if\s+(.+)$")
_ELIF_RE = re.compile(r"^elif\s+(.+)$")


def _parse_for_stmt(tokens: list[Token], i: int) -> tuple[For, int]:
    """Parse a {% for %} statement starting at tokens[i]. Returns (node, next_i)."""
    tok = tokens[i]
    m = _FOR_RE.match(tok.value)
    if not m:
        raise TemplateSyntaxError(f"malformed for statement: {tok.value!r}", tok.lineno)
    var_name = m.group(1)
    if var_name in _RESERVED:
        raise TemplateSyntaxError(
            f"reserved word {var_name!r} used as loop variable", tok.lineno
        )
    iter_expr = parse_value_expr(m.group(2).strip(), tok.lineno)

    body: list[Node] = []
    else_body: list[Node] = []
    in_else = False
    i += 1
    n = len(tokens)

    while i < n:
        t = tokens[i]
        if t.kind == "block":
            v = t.value
            if v == "endfor":
                i += 1
                break
            if v == "else":
                if in_else:
                    raise TemplateSyntaxError("second else in for loop", t.lineno)
                in_else = True
                i += 1
                continue
            if in_else:
                node, i = _parse_inner_block(tokens, i)
                else_body.append(node)
                continue
            node, i = _parse_inner_block(tokens, i)
            body.append(node)
            continue
        # text or var
        if t.kind == "text":
            if t.value:
                (else_body if in_else else body).append(Text(t.value))
        elif t.kind == "var":
            expr = parse_value_expr(t.value, t.lineno)
            (else_body if in_else else body).append(Var(expr, t.lineno))
        i += 1
    else:
        raise TemplateSyntaxError("unterminated for loop", tok.lineno)

    return For(var_name, iter_expr, body, else_body, tok.lineno), i


def _parse_if_stmt(tokens: list[Token], i: int) -> tuple[If, int]:
    """Parse an {% if %} statement starting at tokens[i]. Returns (node, next_i)."""
    tok = tokens[i]
    m = _IF_RE.match(tok.value)
    if not m:
        raise TemplateSyntaxError(
            f"malformed if statement: {tok.value!r}", tok.lineno
        )
    cond = parse_condition(m.group(1).strip(), tok.lineno)
    branches: list[tuple[Condition, list[Node]]] = [(cond, [])]
    else_body: list[Node] = []
    has_else = False
    i += 1
    n = len(tokens)

    while i < n:
        t = tokens[i]
        if t.kind == "block":
            v = t.value
            em = _ELIF_RE.match(v)
            if em:
                if has_else:
                    raise TemplateSyntaxError("elif after else", t.lineno)
                econd = parse_condition(em.group(1).strip(), t.lineno)
                branches.append((econd, []))
                i += 1
                continue
            if v == "else":
                if has_else:
                    raise TemplateSyntaxError("multiple else in if", t.lineno)
                has_else = True
                i += 1
                continue
            if v == "endif":
                i += 1
                break
            # Nested block statement
            node, i = _parse_inner_block(tokens, i)
            if has_else:
                else_body.append(node)
            else:
                branches[-1][1].append(node)
            continue
        # text or var
        if t.kind == "text":
            if t.value:
                if has_else:
                    else_body.append(Text(t.value))
                else:
                    branches[-1][1].append(Text(t.value))
        elif t.kind == "var":
            expr = parse_value_expr(t.value, t.lineno)
            if has_else:
                else_body.append(Var(expr, t.lineno))
            else:
                branches[-1][1].append(Var(expr, t.lineno))
        i += 1
    else:
        raise TemplateSyntaxError("unterminated if block", tok.lineno)

    return If(branches, else_body, tok.lineno), i


def _parse_inner_block(tokens: list[Token], i: int) -> tuple[Node, int]:
    """Parse a nested block statement (for or if) starting at tokens[i].

    Returns (node, next_i).
    """
    t = tokens[i]
    v = t.value
    if v.startswith("for "):
        return _parse_for_stmt(tokens, i)
    if _IF_RE.match(v):
        return _parse_if_stmt(tokens, i)
    raise TemplateSyntaxError(f"unknown statement {v!r}", t.lineno)


def parse(source: str) -> list[Node]:
    """Parse *source* into a list of top-level nodes.

    Raises :class:`TemplateSyntaxError` for any syntax problem.
    """
    tokens = tokenize(source)
    nodes: list[Node] = []
    i = 0
    n = len(tokens)

    while i < n:
        t = tokens[i]
        if t.kind == "text":
            if t.value:
                nodes.append(Text(t.value))
            i += 1
        elif t.kind == "var":
            expr = parse_value_expr(t.value, t.lineno)
            nodes.append(Var(expr, t.lineno))
            i += 1
        elif t.kind == "block":
            v = t.value
            if v.startswith("for "):
                node, i = _parse_for_stmt(tokens, i)
                nodes.append(node)
                continue
            if _IF_RE.match(v):
                node, i = _parse_if_stmt(tokens, i)
                nodes.append(node)
                continue
            raise TemplateSyntaxError(f"unknown statement {v!r}", t.lineno)
        else:
            raise TemplateSyntaxError(f"unexpected token kind {t.kind!r}", t.lineno)

    return nodes
