"""Render parsed tmpl templates against a context."""

from __future__ import annotations

import typing
from collections.abc import Mapping

from .lexer import TemplateRenderError
from .parser import (
    And,
    AtomExpr,
    BareValue,
    Comparison,
    Condition,
    Filter,
    For,
    If,
    Node,
    Not,
    Or,
    Text,
    Var,
    ValueExpr,
    parse,
)

# ---------------------------------------------------------------------------
# Variable resolution
# ---------------------------------------------------------------------------


def _segment_get(value: typing.Any, segment: str | int) -> typing.Any:
    """Apply one segment to a value."""
    if value is None:
        return None
    if isinstance(value, Mapping):
        return value.get(str(segment))
    if isinstance(value, (list, tuple)):
        if isinstance(segment, int) and 0 <= segment < len(value):
            return value[segment]
        return None
    if isinstance(segment, str) and not segment.startswith("_"):
        return getattr(value, segment, None)
    return None


def _resolve_value(expr: ValueExpr, ctx: dict[str, typing.Any], lineno: int) -> typing.Any:
    """Resolve a value expression against a context."""
    if isinstance(expr, AtomExpr):
        if expr.kind == "string":
            return expr.value
        if expr.kind == "int":
            return expr.value
        if expr.kind == "var":
            assert expr.path is not None
            val = ctx.get(expr.path[0])
            for seg in expr.path[1:]:
                val = _segment_get(val, seg)
            return val
        raise TemplateRenderError(f"unknown atom kind {expr.kind!r}", lineno)
    if isinstance(expr, Filter):
        val = _resolve_value(expr.sub, ctx, lineno)
        return _apply_filter(expr.name, expr.arg, expr.arg_kind, val, lineno)
    raise TemplateRenderError("unknown expression type", lineno)


def _output_text(value: typing.Any) -> str:
    """Convert a value to its output text."""
    if value is None:
        return ""
    return str(value)


# ---------------------------------------------------------------------------
# Filters
# ---------------------------------------------------------------------------


def _apply_filter(
    name: str,
    arg: typing.Any,
    arg_kind: str | None,
    value: typing.Any,
    lineno: int,
) -> typing.Any:
    if name == "upper":
        return _output_text(value).upper()
    if name == "lower":
        return _output_text(value).lower()
    if name == "trim":
        return _output_text(value).strip()
    if name == "length":
        if value is None:
            return 0
        try:
            return len(value)
        except TypeError:
            raise TemplateRenderError(
                f"cannot take length of {type(value).__name__}", lineno
            ) from None
    if name == "first":
        if value is None:
            return None
        try:
            items = list(value)
        except TypeError:
            raise TemplateRenderError(
                f"first: {type(value).__name__} is not iterable", lineno
            ) from None
        return items[0] if items else None
    if name == "last":
        if value is None:
            return None
        try:
            items = list(value)
        except TypeError:
            raise TemplateRenderError(
                f"last: {type(value).__name__} is not iterable", lineno
            ) from None
        return items[-1] if items else None
    if name == "reverse":
        if value is None:
            return None
        if isinstance(value, str):
            return value[::-1]
        if isinstance(value, (list, tuple)):
            return list(value)[::-1]
        raise TemplateRenderError(
            f"reverse: {type(value).__name__} not supported", lineno
        )
    if name == "join":
        if value is None:
            return ""
        sep = arg  # validated at parse time to be str
        try:
            return sep.join(_output_text(item) for item in value)
        except TypeError:
            raise TemplateRenderError(
                f"join: {type(value).__name__} is not iterable", lineno
            ) from None
    if name == "default":
        if value is None or value == "":
            return arg
        return value
    if name == "truncate":
        text = _output_text(value)
        limit: int = arg  # validated at parse time to be int >= 0
        if len(text) > limit:
            return text[:limit] + "..."
        return text
    if name == "items":
        if value is None:
            return []
        if isinstance(value, Mapping):
            return list(value.items())
        raise TemplateRenderError(
            f"items: {type(value).__name__} is not a mapping", lineno
        )
    raise TemplateRenderError(f"unknown filter {name!r}", lineno)


# ---------------------------------------------------------------------------
# Condition evaluation
# ---------------------------------------------------------------------------


def _eval_condition(
    cond: Condition, ctx: dict[str, typing.Any], lineno: int
) -> bool:
    if isinstance(cond, BareValue):
        return bool(_resolve_value(cond.expr, ctx, lineno))
    if isinstance(cond, Comparison):
        left = _resolve_value(cond.left, ctx, lineno)
        right = _resolve_value(cond.right, ctx, lineno)
        return _compare(left, cond.op, right, lineno)
    if isinstance(cond, Not):
        return not _eval_condition(cond.sub, ctx, lineno)
    if isinstance(cond, And):
        if not _eval_condition(cond.left, ctx, lineno):
            return False
        return _eval_condition(cond.right, ctx, lineno)
    if isinstance(cond, Or):
        if _eval_condition(cond.left, ctx, lineno):
            return True
        return _eval_condition(cond.right, ctx, lineno)
    raise TemplateRenderError("unknown condition type", lineno)


def _compare(
    left: typing.Any, op: str, right: typing.Any, lineno: int
) -> bool:
    if op == "==":
        return left == right
    if op == "!=":
        return left != right
    try:
        if op == "<":
            return left < right
        if op == "<=":
            return left <= right
        if op == ">":
            return left > right
        if op == ">=":
            return left >= right
    except TypeError:
        raise TemplateRenderError(
            f"cannot compare {type(left).__name__} and {type(right).__name__} with {op!r}",
            lineno,
        ) from None
    raise TemplateRenderError(f"unknown operator {op!r}", lineno)


# ---------------------------------------------------------------------------
# Node rendering
# ---------------------------------------------------------------------------


def _render_nodes(
    nodes: list[Node], ctx: dict[str, typing.Any], out: list[str], lineno: int
) -> None:
    for node in nodes:
        if isinstance(node, Text):
            out.append(node.value)
        elif isinstance(node, Var):
            val = _resolve_value(node.expr, ctx, node.lineno)
            out.append(_output_text(val))
        elif isinstance(node, For):
            _render_for(node, ctx, out)
        elif isinstance(node, If):
            _render_if(node, ctx, out)
        else:
            raise TemplateRenderError("unknown node type", lineno)


def _render_for(
    node: For, ctx: dict[str, typing.Any], out: list[str]
) -> None:
    items_val = _resolve_value(node.iter_expr, ctx, node.lineno)

    if items_val is None:
        items: list[typing.Any] = []
    elif isinstance(items_val, Mapping):
        items = list(items_val.keys())
    elif isinstance(items_val, str):
        items = list(items_val)
    else:
        try:
            items = list(items_val)
        except TypeError:
            raise TemplateRenderError(
                f"for: {type(items_val).__name__} is not iterable", node.lineno
            ) from None

    if items:
        length = len(items)
        saved_var = ctx.get(node.var)
        had_var = node.var in ctx
        had_loop = "loop" in ctx
        saved_loop = ctx.get("loop") if had_loop else None

        for idx, item in enumerate(items):
            ctx[node.var] = item
            ctx["loop"] = {
                "index": idx + 1,
                "index0": idx,
                "first": idx == 0,
                "last": idx == length - 1,
                "length": length,
            }
            _render_nodes(node.body, ctx, out, node.lineno)

        if had_var:
            ctx[node.var] = saved_var
        else:
            ctx.pop(node.var, None)
        if had_loop:
            ctx["loop"] = saved_loop
        else:
            ctx.pop("loop", None)
    else:
        _render_nodes(node.else_body, ctx, out, node.lineno)


def _render_if(
    node: If, ctx: dict[str, typing.Any], out: list[str]
) -> None:
    for cond, body in node.branches:
        # Use the node's lineno as a reasonable line for the condition;
        # for elif we ideally would track the elif's line, but the If node
        # stores the original if's line.  This is acceptable per the spec
        # since the spec says "the line of that elif" — we need to track
        # it.  For now, use the If's lineno as a fallback.
