"""Tokenization for the tmpl template language."""

from __future__ import annotations

import typing


class TemplateError(Exception):
    """Base class for all tmpl errors."""

    def __init__(self, message: str, lineno: int) -> None:
        super().__init__(message, lineno)
        self.message = message
        self.lineno = lineno

    def __str__(self) -> str:
        return f"line {self.lineno}: {self.message}"


class TemplateSyntaxError(TemplateError):
    """Raised for template syntax problems."""


class TemplateRenderError(TemplateError):
    """Raised for problems that surface while rendering."""


class Token(typing.NamedTuple):
    kind: str
    value: str
    lineno: int


def tokenize(source: str) -> list[Token]:
    """Split *source* into text, variable and block tokens.

    Comments are dropped but keep the surrounding text tokens separate.
    A tag's value is the text between the opening and closing delimiters
    with surrounding whitespace stripped.  The ``lineno`` of every token
    is the line on which the token (or, for tags, the opening delimiter)
    starts.
    """
    tokens: list[Token] = []
    i = 0
    n = len(source)
    text_start = 0

    def _line_of(idx: int) -> int:
        return source.count("\n", 0, idx) + 1

    def _flush(end: int) -> None:
        nonlocal text_start
        if end > text_start:
            tokens.append(Token("text", source[text_start:end], _line_of(text_start)))
        text_start = end

    while i < n:
        if source.startswith("{{", i):
            _flush(i)
            end = source.find("}}", i + 2)
            if end == -1:
                raise TemplateSyntaxError("unclosed variable tag", _line_of(i))
            tokens.append(Token("var", source[i + 2:end].strip(), _line_of(i)))
            i = end + 2
            text_start = i
        elif source.startswith("{%", i):
            _flush(i)
            end = source.find("%}", i + 2)
            if end == -1:
                raise TemplateSyntaxError("unclosed block tag", _line_of(i))
            tokens.append(Token("block", source[i + 2:end].strip(), _line_of(i)))
            i = end + 2
            text_start = i
        elif source.startswith("{#", i):
            _flush(i)
            end = source.find("#}", i + 2)
            if end == -1:
                raise TemplateSyntaxError("unclosed comment tag", _line_of(i))
            # Flush up to the start of the comment so that text before it
            # becomes its own token, then set text_start to the end of the
            # comment so that text after it becomes a separate token.
            i = end + 2
            text_start = i
        else:
            i += 1

    _flush(n)
    return tokens
