# ---------------------------------------------------------------------------
# Public API
# ---------------------------------------------------------------------------


class Template:
    """A parsed template that can be rendered multiple times."""

    def __init__(self, source: str) -> None:
        self._nodes = parse(source)

    def render(
        self, context: dict[str, typing.Any] | None = None, **kwargs: typing.Any
    ) -> str:
        ctx: dict[str, typing.Any] = {}
        if context is not None:
            ctx.update(context)
