    def __init__(self, value):
        self.value = value

class RefNode(Node):
    def __init__(self, name):
        self.name = name

class UnaryNode(Node):
    def __init__(self, op, operand):
        self.op = op
        self.operand = operand

class BinaryNode(Node):
    def __init__(self, op, left, right):
        self.op = op
        self.left = left
        self.right = right

# Tokenizer
TOKEN_RE = re.compile(r'''
    (?P<whitespace>\s+)
  | (?P<number>\d+(?:\.\d+)?)
  | (?P<ref>[A-Za-z]+\d+)
  | (?P<op>[-+*/()])
''', re.VERBOSE)

def _tokenize(source):
    tokens = []
    pos = 0
    while pos < len(source):
        m = TOKEN_RE.match(source, pos)
        if not m:
            if source[pos] != ' ': # We handle whitespace in regex, but if it matches nothing and isn't space, it's invalid
                raise FormulaError(f"Invalid character at position {pos}: {source[pos]}")
            raise FormulaError(f"Invalid character at position {pos}")
        if m.lastgroup == 'whitespace':
            pos = m.end()
            continue
        tokens.append((m.lastgroup, m.group()))
        pos = m.end()
    return tokens

# Parser
class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def consume(self):
        token = self.peek()
        if token is None:
            raise FormulaError("Unexpected end of input")
        self.pos += 1
        return token

    def expect(self, kind, value=None):
        token = self.peek()
        if token is None:
            raise FormulaError(f"Expected {kind}, got end of input")
        if token[0] != kind:
            raise FormulaError(f"Expected {kind}, got {token[0]}")
        if value is not None and token[1] != value:
            raise FormulaError(f"Expected {value}, got {token[1]}")
        return self.consume()

    def parse_expr(self):
        node = self.parse_term()
        while True:
            token = self.peek()
            if token and token[0] == 'op' and token[1] in ('+', '-'):
                self.consume()
                right = self.parse_term()
                node = BinaryNode(token[1], node, right)
            else:
                break
        return node

    def parse_term(self):
        node = self.parse_unary()
        while True:
            token = self.peek()
            if token and token[0] == 'op' and token[1] in ('*', '/'):
                self.consume()
                right = self.parse_unary()
                node = BinaryNode(token[1], node, right)
            else:
                break
        return node

    def parse_unary(self):
        token = self.peek()
        if token and token[0] == 'op' and token[1] in ('+', '-'):
            self.consume()
            operand = self.parse_unary()
            return UnaryNode(token[1], operand)
        return self.parse_primary()

    def parse_primary(self):
        token = self.peek()
        if token is None:
            raise FormulaError("Unexpected end of input in primary")

        kind, val = token

        if kind == 'op' and val == '(':
            self.consume()
            node = self.parse_expr()
            self.expect('op', ')')
            return node
        elif kind == 'number':
            self.consume()
            if '.' in val:
                return NumberNode(float(val))
            else:
                return NumberNode(int(val))
        elif kind == 'ref':
            self.consume()
            # Validate reference format: 1 letter, row 1-999, no leading zeros
            col = val[0].upper()
            row_str = val[1:]

            if not row_str.isdigit():
                raise FormulaError(f"Invalid reference: {val}")

            # Check leading zero
            if len(row_str) > 1 and row_str[0] == '0':
                raise FormulaError(f"Reference with leading zero: {val}")

            row = int(row_str)
            if row < 1 or row > 999:
                raise FormulaError(f"Row out of bounds: {val}")

            # Column must be single letter A-Z
            if not ('A' <= col <= 'Z'):
                raise FormulaError(f"Invalid column: {val}")

            return RefNode(f"{col}{row}")
        else:
            raise FormulaError(f"Unexpected token: {token}")

def parse_formula(source):
    if not source:
        raise FormulaError("Empty formula")

    tokens = _tokenize(source)
    if not tokens:
        raise FormulaError("Empty formula")

    parser = Parser(tokens)
    try:
        tree = parser.parse_expr()
    except FormulaError:
        raise
    except Exception as e:
        raise FormulaError(str(e))

    # Ensure all tokens were consumed
    if parser.pos != len(parser.tokens):
        raise FormulaError(f"Incomplete expression, unexpected token: {parser.peek()}")

    return tree

def references(tree):
    refs = set()
    _collect_refs(tree, refs)
    return refs

def _collect_refs(node, refs):
    if isinstance(node, RefNode):
        refs.add(node.name)
    elif isinstance(node, UnaryNode):
        _collect_refs(node.operand, refs)
    elif isinstance(node, BinaryNode):
        _collect_refs(node.left, refs)
        _collect_refs(node.right, refs)
    # NumberNode has no refs

def _is_error(val):
    return isinstance(val, ErrorValue)

def _is_text(val):
    return isinstance(val, str) and not isinstance(val, ErrorValue)

def _is_number(val):
    return isinstance(val, (int, float)) and not isinstance(val, bool)

def evaluate(tree, lookup):
    return _eval_node(tree, lookup)

def _eval_node(node, lookup):
    if isinstance(node, NumberNode):
        return node.value

    if isinstance(node, RefNode):
        val = lookup(node.name)
        if val is None:
            return 0
        return val

    if isinstance(node, UnaryNode):
        operand_val = _eval_node(node.operand, lookup)
        if _is_error(operand_val):
            return operand_val
        if _is_text(operand_val):
            return ERROR_GENERIC
        if node.op == '-':
            return -operand_val
        else:
            return operand_val

    if isinstance(node, BinaryNode):
        left_val = _eval_node(node.left, lookup)
        right_val = _eval_node(node.right, lookup)

        # Propagate errors
        if _is_error(left_val):
            return left_val
        if _is_error(right_val):
            return right_val

        # Text check
        if _is_text(left_val) or _is_text(right_val):
            return ERROR_GENERIC

        op = node.op

        if op == '+':
            if isinstance(left_val, int) and isinstance(right_val, int):
                return left_val + right_val
            else:
                return float(left_val) + float(right_val)

        if op == '-':
            if isinstance(left_val, int) and isinstance(right_val, int):
                return left_val - right_val
            else:
                return float(left_val) - float(right_val)

        if op == '*':
            if isinstance(left_val, int) and isinstance(right_val, int):
                return left_val * right_val
            else:
                return float(left_val) * float(right_val)

        if op == '/':
            if right_val == 0:
                return ERROR_GENERIC
            return float(left_val) / float(right_val)

    raise FormulaError("Unknown node type")
