class DependencyGraph:
    def __init__(self):
        # Maps cell -> set of precedent cells (cells it depends on)
        self._precedents = {}
        # Maps cell -> set of dependent cells (cells that depend on it)
        self._dependents = {}

    def set_dependencies(self, cell, precedents):
        # Remove old links
        if cell in self._precedents:
            old_precs = self._precedents[cell]
            for p in old_precs:
                if cell in self._dependents.get(p, set()):
                    self._dependents[p].discard(cell)

        # Set new links
        new_precs = set(precedents)
        self._precedents[cell] = new_precs

        # Update reverse dependencies
        # First, ensure cell is in dependents dict if it has any dependents later
        if not self._dependents.get(cell):
             self._dependents[cell] = set()

        for p in new_precs:
            if p not in self._dependents:
                self._dependents[p] = set()
            self._dependents[p].add(cell)

        # Clean up empty sets in dependents? 
        # Not strictly necessary for logic, but keeps memory tidy.
        # However, we must be careful not to remove keys that might be queried.
        # The spec says "empty set for unknown cell", so we can leave empty sets or remove them.
        # Removing is safer to distinguish "known but no deps" vs "unknown"?
        # Actually, precedents(cell) should return empty set for unknown.
        # If I remove the key from _precedents, it's unknown.
        # If I keep it with empty set, it's known but empty.
        # The spec says "replace cell's precedents ... empty removes them".
        # This implies the cell still exists in the graph structure if we just set it to empty?
        # "All names it receives are already upper case."
        # Let's keep the key in _precedents if it was set, even if empty, 
        # unless we want to strictly track "known" cells.
        # However, for `all_dependents` and `cycle_cells`, it's better to iterate over keys.

        # Let's refine: 
        # If I call set_dependencies('A', []), A should probably not appear in cycle checks if it has no refs.
        # But if A had refs before, and I clear them, A should no longer be in cycles.

        # Let's just keep the dict keys. 
        # If a cell is never touched, it's not in the dict.
        # If a cell is touched with empty set, it's in the dict with empty set.
        # This distinction might matter if we iterate all cells? 
        # The Sheet class manages which cells exist. The Graph just manages links.
        # So it's fine.

    def precedents(self, cell):
        return self._precedents.get(cell, set())

    def dependents(self, cell):
        return self._dependents.get(cell, set())

    def all_dependents(self, cell):
        result = set()
        # BFS/DFS from cell's dependents
        stack = list(self._dependents.get(cell, set()))
        while stack:
            current = stack.pop()
            if current not in result:
                result.add(current)
                next_deps = self._dependents.get(current, set())
                for d in next_deps:
                    if d not in result:
                        stack.append(d)
        return result

    def cycle_cells(self):
        # Find all cells that are part of a cycle.
        # A cell is on a cycle if it can reach itself via precedents.
        # We can do this by checking for each cell if it's in the set of 
        # cells reachable from its own precedents?
        # Or simpler: A cell C is on a cycle if C is in all_precedents(C)?
        # No, `all_dependents` goes forward. We need "all precedents" (transitive).

        # Let's implement a helper to get all transitive precedents.
        def get_all_precedents(start):
            visited = set()
            stack = list(self._precedents.get(start, set()))
            while stack:
                current = stack.pop()
                if current not in visited:
                    visited.add(current)
                    for p in self._precedents.get(current, set()):
                        if p not in visited:
                            stack.append(p)
            return visited

        cycles = set()
        # Iterate over all cells that have any precedents or dependents?
        # Actually, only cells in _precedents can be on a cycle (or have self ref).
        # A cell with no precedents cannot be on a cycle.
        for cell in list(self._precedents.keys()):
            # A cell is on a cycle if it is one of its own transitive precedents
            # OR if it has a direct self-reference?
            # If A -> A, then get_all_precedents(A) will include A?
            # Let's trace: 
            # start=A. stack=[A] (from _precedents[A])
            # pop A. visited={A}.
            # So yes, if A is in _precedents[A], it will be added to visited.

            all_precs = get_all_precedents(cell)
            if cell in all_precs:
                cycles.add(cell)

        return cycles
