import re
from collections import deque
from .formula import parse_formula, references, evaluate, FormulaError, ERROR_CYCLE
from .graph import DependencyGraph

# Regex for valid cell names: Single uppercase letter A-Z, digits 1-999, no leading zeros
CELL_NAME_RE = re.compile(r'^([A-Z])([1-9][0-9]{0,2})$')

def _normalize_name(name):
    if not isinstance(name, str):
        raise ValueError("Cell name must be a string")
    upper_name = name.upper()
    match = CELL_NAME_RE.match(upper_name)
    if not match:
        raise ValueError(f"Invalid cell name: {name}")
    return upper_name

def _row_major_sort_key(name):
    col = name[0]
    row = int(name[1:])
    return (row, col)

class Sheet:
    def __init__(self):
        self._cells = {}       # name -> value
        self._raw = {}         # name -> raw input string
        self._graph = DependencyGraph()
        self._formula_trees = {} # name -> parsed tree
        self.evaluations = 0

    def set(self, name, raw):
        if not isinstance(raw, str):
            raise TypeError("Raw input must be a string")

        cell = _normalize_name(name)

        # Determine new value and dependencies
        if raw == '':
            new_value = None
            is_formula = False
            tree = None
            deps = set()
        elif raw.startswith('='):
            is_formula = True
            try:
                tree = parse_formula(raw[1:])
            except FormulaError as e:
                # Re-raise, sheet unchanged
                raise e
            deps = references(tree)
            new_value = None # Placeholder, actual value set during recalc
        else:
            # Check if it's a number
            stripped = raw.strip()
            num_match = re.fullmatch(r'-?\d+(?:\.\d+)?', stripped)
            if num_match:
                if '.' in stripped:
                    new_value = float(stripped)
                else:
                    new_value = int(stripped)
                is_formula = False
                tree = None
                deps = set()
            else:
                new_value = raw # Store exactly as given
                is_formula = False
                tree = None
                deps = set()

        # Update Graph
        self._graph.set_dependencies(cell, deps)

        # Update stored raw and tree
        self._raw[cell] = raw
        if is_formula:
            self._formula_trees[cell] = tree
        else:
            if cell in self._formula_trees:
                del self._formula_trees[cell]

        # If it's not a formula, its value is immediate
        if not is_formula:
            self._cells[cell] = new_value
        else:
            # Value will be updated in recalc phase

        # Determine affected cells: cell itself + all_dependents
        affected = self._graph.all_dependents(cell)
        affected.add(cell)

        # Identify cycle cells in the current graph state
        cycle_cells = self._graph.cycle_cells()

        # Identify formula cells in affected that need evaluation
        # They are formula cells that are NOT on a cycle
        cells_to_eval = set()
        for c in affected:
            if c in self._formula_trees:
                if c not in cycle_cells:
                    cells_to_eval.add(c)

        # First, set #CYCLE! for any formula cells in affected that ARE on a cycle
        # This must happen BEFORE evaluating other cells, so that lookups for
        # these cells return the correct error value.
        for c in affected:
            if c in self._formula_trees and c in cycle_cells:
                self._cells[c] = ERROR_CYCLE

        # Topological sort of cells_to_eval based on dependencies within the set
        # We only care about ordering relative to other cells being evaluated in this batch.
        # Dependencies on cells outside the batch are already up-to-date (or just set).

        # Build local in-degree map
        in_degree = {c: 0 for c in cells_to_eval}
        adj = {c: [] for c in cells_to_eval}

        for u in cells_to_eval:
            for v in self._graph.precedents(u):
                if v in cells_to_eval:
                    # u depends on v, so v comes before u
                    adj[v].append(u)
                    in_degree[u] += 1

        queue = deque([c for c in cells_to_eval if in_degree[c] == 0])

        order = []
        while queue:
            node = queue.popleft()
            order.append(node)
            for neighbor in adj[node]:
                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 0:
                    queue.append(neighbor)

        # Evaluate in topological order
        for c in order:
            tree = self._formula_trees[c]

            def lookup(n):
                return self._cells.get(n)

            val = evaluate(tree, lookup)
            self._cells[c] = val
            self.evaluations += 1

        return sorted(affected, key=_row_major_sort_key)

    def get(self, name):
        cell = _normalize_name(name)
        return self._cells.get(cell)

    def raw(self, name):
        cell = _normalize_name(name)
        return self._raw.get(cell, '')

    def cells(self):
        active_cells = [name for name, val in self._cells.items() if val is not None]
        return sorted(active_cells, key=_row_major_sort_key)
