class DependencyGraph:
    def __init__(self):
        # Maps cell -> set of precedent cells (cells it depends on)
        self._precedents = {}
        # Maps cell -> set of dependent cells (cells that depend on it)
        self._dependents = {}

    def set_dependencies(self, cell, precedents):
        # Remove old links
        if cell in self._precedents:
            old_precs = self._precedents[cell]
            for p in old_precs:
                if p in self._dependents:
                    self._dependents[p].discard(cell)
                    if not self._dependents[p]:
                        del self._dependents[p]

        # Set new links
        new_precs = set(precedents)

        if new_precs:
            self._precedents[cell] = new_precs
            for p in new_precs:
                if p not in self._dependents:
                    self._dependents[p] = set()
                self._dependents[p].add(cell)
        else:
            # If new dependencies are empty, remove cell from _precedents
            self._precedents.pop(cell, None)
            # Note: cell might still be a dependent of other cells, 
            # which is handled by the _dependents map keyed by predecessors.
            # We do not need to clean up cell from _dependents here because 
            # _dependents is keyed by the *predecessor*, not the dependent.

    def precedents(self, cell):
        return self._precedents.get(cell, set())

    def dependents(self, cell):
        return self._dependents.get(cell, set())

    def all_dependents(self, cell):
        result = set()
        stack = list(self._dependents.get(cell, set()))
        while stack:
            current = stack.pop()
            if current not in result:
                result.add(current)
                next_deps = self._dependents.get(current, set())
                for d in next_deps:
                    if d not in result:
                        stack.append(d)
        return result

    def cycle_cells(self):
        cycles = set()

        def get_all_precedents(start):
            visited = set()
            stack = list(self._precedents.get(start, set()))
            while stack:
                current = stack.pop()
                if current not in visited:
                    visited.add(current)
                    for p in self._precedents.get(current, set()):
                        if p not in visited:
                            stack.append(p)
            return visited

        # Iterate over all cells that have precedents
        for cell in list(self._precedents.keys()):
            all_precs = get_all_precedents(cell)
            if cell in all_precs:
                cycles.add(cell)

        return cycles
